package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class MediaSessionTest {
 private void add(PublicMediaSession s,String origin,String...cookies){s.receive(origin,Collections.singletonMap("Set-Cookie",Arrays.asList(cookies)));}
 @Test public void anonymousSessionReachesOnlyMatchingHttpsMediaHosts()throws Exception{PublicMediaSession s=new PublicMediaSession();add(s,"https://www.tiktok.com/@test/video/7412345678901234567","ttwid=guest-token; Domain=.tiktok.com; Path=/; Secure; HttpOnly","local=one; Path=/video");assertEquals("ttwid=guest-token",s.header("https://v16-webapp-prime.tiktok.com/video/file"));assertTrue(s.header("https://www.tiktok.com/video/file").contains("local=one"));assertFalse(s.header("https://www.tiktok.com/videography").contains("local="));assertEquals("",s.header("https://tiktok.com.evil.org/video"));assertEquals("",s.header("https://example.com/video"));assertEquals("",s.header("http://www.tiktok.com/video"));assertEquals(s.header("https://v16-webapp-prime.tiktok.com/video/file"),PublicMediaSession.restore(s.snapshot()).header("https://v16-webapp-prime.tiktok.com/video/file"));}
 @Test public void invalidDomainsDeletionAndCorruptHandoffDoNotLeakCookies()throws Exception{PublicMediaSession s=new PublicMediaSession();add(s,"https://www.tiktok.com/","bad=x; Domain=.com","other=x; Domain=evil.com","ttwid=one; Domain=.tiktok.com; Path=/");assertEquals("ttwid=one",s.header("https://www.tiktok.com/"));add(s,"https://www.tiktok.com/","ttwid=gone; Domain=.tiktok.com; Path=/; Max-Age=0");assertEquals("",s.header("https://www.tiktok.com/"));for(String raw:new String[]{"bad","{\"version\":2,\"cookies\":[]}","{\"version\":1,\"cookies\":[{\"name\":\"x\",\"value\":\"v\",\"domain\":\"evil.com\",\"path\":\"/\",\"hostOnly\":false,\"secure\":true,\"expires\":-1}]}"})try{PublicMediaSession.restore(raw);fail();}catch(java.io.IOException expected){}}
}
